package com.bank.spark.model;

// Holds the recommended operation and why.
public class PartitionDecision {
    private final String operation;      // "coalesce(n)" or "repartition(n)"
    private final int upstreamParallelism;
    private final String reasoning;

    public PartitionDecision(String operation, int upstreamParallelism, String reasoning) {
        this.operation = operation;
        this.upstreamParallelism = upstreamParallelism;
        this.reasoning = reasoning;
    }

    public String getOperation() { return operation; }
    public int getUpstreamParallelism() { return upstreamParallelism; }
    public String getReasoning() { return reasoning; }
}
