package com.bank.spark.service;

import com.bank.spark.model.PartitionDecision;

// Recommends coalesce vs repartition based on direction and upstream cost.
public class PartitionAdvisor {

    // Increasing the count always requires a shuffle, so repartition.
    public PartitionDecision adviseIncrease(int current, int target) {
        if (target <= current) {
            throw new IllegalArgumentException("Not an increase: " + current + " -> " + target);
        }
        return new PartitionDecision("repartition(" + target + ")", target,
                "Increasing requires a shuffle to create new partitions");
    }

    // Reducing: coalesce is cheap, BUT if upstream work is heavy and target is tiny,
    // recommend repartition to keep upstream parallel.
    public PartitionDecision adviseReduce(int sourceParallelism, int target, boolean upstreamHeavy) {
        if (target == 1 && upstreamHeavy) {
            return new PartitionDecision("repartition(1)", sourceParallelism,
                    "coalesce(1) would collapse heavy upstream into 1 task; repartition keeps it parallel");
        }
        return new PartitionDecision("coalesce(" + target + ")", target,
                "Narrow merge, no shuffle; fine because upstream work is light");
    }
}
