package com.bank.spark;

import com.bank.spark.model.PartitionDecision;
import com.bank.spark.service.PartitionAdvisor;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PartitionAdvisorDemo {

    private static final Logger log = Logger.getLogger(PartitionAdvisorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PartitionAdvisor advisor = new PartitionAdvisor();

        // Case 1: regulatory report, one file, heavy aggregation upstream.
        PartitionDecision oneFileHeavy = advisor.adviseReduce(200, 1, true);
        log.info(() -> "One-file report, heavy upstream -> " + oneFileHeavy.getOperation()
                + " | upstream tasks kept: " + oneFileHeavy.getUpstreamParallelism());
        log.info("Reason: " + oneFileHeavy.getReasoning());

        // Case 2: shrink tiny partitions after a light filter.
        PartitionDecision shrinkLight = advisor.adviseReduce(200, 10, false);
        log.info(() -> "Shrink after light filter -> " + shrinkLight.getOperation());
        log.info("Reason: " + shrinkLight.getReasoning());

        // Case 3: raise parallelism before a heavy join.
        PartitionDecision raise = advisor.adviseIncrease(8, 64);
        log.info(() -> "Raise parallelism -> " + raise.getOperation());
        log.info("Reason: " + raise.getReasoning());

        // The dangerous mistake demonstrated:
        log.warning("Avoid coalesce(1) when upstream is heavy — it serializes all work into one task.");
    }
}

